function validate([cost, time]) {
  if (cost.length < 1 || cost.length > 500) return 'cost needs 1 to 500 values.';
  if (time.length !== cost.length) return 'cost and time must have the same length.';
  if (cost.some(v => v < 1 || v > 1000000)) return 'Each cost is between 1 and 10^6.';
  if (time.some(v => v < 1 || v > 500)) return 'Each time is between 1 and 500.';
  return null;
}

