function paintWalls(cost, time) {
  const n = cost.length;
  const dp = new Array(n + 1).fill(Infinity);
  dp[0] = 0;

  for (let i = 0; i < n; i++) {
    for (let covered = n; covered > 0; covered--) {
      const before = Math.max(0, covered - time[i] - 1);
      dp[covered] = Math.min(dp[covered], dp[before] + cost[i]);
    }
  }
  return dp[n];
}

