function paintWalls(cost, time) {
  // Walk the walls in order; paying adds time[i] of free-painter time, a free wall uses 1.
  // A choice works when the balance never ends negative, i.e. paid time >= free walls.
  const n = cost.length;
  const memo = new Map();
  const go = (i, balance) => {
    if (balance >= n - i) return 0;
    if (i === n) return Infinity;
    const key = i * 4096 + balance + 2048;
    if (memo.has(key)) return memo.get(key);
    const result = Math.min(cost[i] + go(i + 1, balance + time[i]), go(i + 1, balance - 1));
    memo.set(key, result);
    return result;
  };
  return go(0, 0);
}

