function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 500;
    const cost = Array.from({ length: n }, () => int(1, 1000000));
    const time = Array.from({ length: n }, () => (rand() < 0.9 ? int(1, 5) : int(1, 500)));
    return [cost, time];
  }
  const n = int(1, 10);
  const costTop = rand() < 0.5 ? 10 : 1000000;
  const timeTop = rand() < 0.7 ? 3 : 500;
  const cost = Array.from({ length: n }, () => int(1, costTop));
  const time = Array.from({ length: n }, () => int(1, timeTop));
  return [cost, time];
}
